sys_script.script:
(function executeRule(current, previous /* null when async */) {

    /* =====================================================
       CAMPUSMATCH — GENERATE COLLECTION TOKEN
    ===================================================== */


    /* -----------------------------------------------------
       GENERATE TOKEN ONLY IF ONE DOES NOT ALREADY EXIST
    ----------------------------------------------------- */

    var existingToken =
        current.getValue(
            'collection_toke0'
        );


    if (!existingToken) {

        var newToken =
            gs.generateGUID();


        current.setValue(
            'collection_toke0',
            newToken
        );

    }


    /* -----------------------------------------------------
       RESET HANDOVER STATUS
    ----------------------------------------------------- */

    current.setValue(
        'handover_completed',
        false
    );


    /* -----------------------------------------------------
       CLEAR PREVIOUS HANDOVER DETAILS
    ----------------------------------------------------- */

    current.setValue(
        'handed_over_by',
        ''
    );


    current.setValue(
        'handed_over_on',
        ''
    );


})(current, previous);
